#!/usr/bin/env node
/**
 * calendar-extractor — generated by JavisSkills/skill-creator (improved build)
 * Triggered by openclaw cron, by the openclaw webhook (per-unit auto path), OR
 * by the LLM on user-typed commands.
 *
 * Two subcommands (the cron/webhook drive both via the agent):
 *   fetch  GET recent session transcripts from javis-server and print them as JSON
 *          to stdout. The agent reads this and extracts the calendar events.
 *          With --session <id> / --kbd-input <id> the payload is filtered to a
 *          single unit (the webhook auto path); with no flags it returns the
 *          whole time window (the manual path), unchanged.
 *   push   read an extracted-events JSON array on stdin, dedup it against per-user
 *          local state, mirror it to the server skill_data store (best-effort), and
 *          push a markdown digest of the NEW events to the user's iOS chat.
 *          With --unit <unitKey> it runs the idempotent per-unit AUTO path; with
 *          no --unit it runs the MANUAL gap-fill path.
 *
 * Usage:
 *   node calendar-extractor.js <userId> fetch [--hours N] [--limit N]
 *   node calendar-extractor.js <userId> fetch --session <sessionId> [--hours N]
 *   node calendar-extractor.js <userId> fetch --kbd-input <inputId> [--hours N]
 *   node calendar-extractor.js <userId> push  [--unit <unitKey>] < events.json
 *   node calendar-extractor.js --help
 *
 * Env:
 *   OPENCLAW_GATEWAY_TOKEN  required for fetch/push — Bearer auth to javis-server
 *                           (injected automatically inside the openclaw container)
 *   JAVIS_SERVER_URL        optional — defaults to http://javis-server:8000
 *
 * Verified endpoints (javis-server):
 *   GET  /api/transcripts/recent  (get_gateway_user; params since, limit)
 *   POST /api/agent/push          (get_gateway_user; {skill, content, session_id?})
 *   POST /api/skill/data          (get_gateway_user; upsert by dedup_key)
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { resolveUserId, safeUserPath, readJson, writeJson } = require('./data');
const {
  isoOrNull,
  normalizeEvent,
  dedupKey,
  unitKeyFor,
  pruneSeen,
  pruneExtractedUnits,
  partitionForManual,
} = require('./lib');

const SLUG = 'calendar-extractor';
const SERVER = process.env.JAVIS_SERVER_URL || 'http://javis-server:8000';

// argv is parsed lazily so `require()`-ing this module from a unit test is
// side-effect-free (no --help exit, no userId sanitize/exit on the test runner's
// argv). The CLI entry point (main) is the only caller of parseArgv().
const SUBCOMMANDS = ['fetch', 'push'];
let userId, subcommand, rest;

function parseArgv() {
  if (process.argv.includes('--help')) {
    console.log([
      'Usage:',
      '  node calendar-extractor.js <userId> fetch [--hours N] [--limit N]',
      '  node calendar-extractor.js <userId> fetch --session <sessionId> [--hours N]',
      '  node calendar-extractor.js <userId> fetch --kbd-input <inputId> [--hours N]',
      '  node calendar-extractor.js <userId> push  [--unit <unitKey>] < events.json',
      '',
      'fetch  GET recent transcripts from javis-server -> JSON on stdout',
      '         --session/--kbd-input filter to one unit (webhook auto path)',
      'push   read extracted-events JSON on stdin -> dedup + push markdown digest to iOS',
      '         --unit runs the idempotent per-unit auto path; no --unit fills gaps',
    ].join('\n'));
    process.exit(0);
  }

  // userId is optional. Positional parsing must not mistake a bare subcommand
  // (e.g. `calendar-extractor.js fetch`) for the userId.
  const a2 = process.argv[2];
  if (SUBCOMMANDS.includes(a2)) {
    // userId omitted — argv[2] is the subcommand (zero-config interactive use)
    userId = resolveUserId(null);
    subcommand = a2;
    rest = process.argv.slice(3);
  } else {
    // explicit userId provided (back-compat, e.g. cron-issued commands)
    userId = resolveUserId(a2);
    subcommand = process.argv[3] || 'fetch';
    rest = process.argv.slice(4);
  }
}

function getFlag(name, dflt) {
  const i = rest.indexOf(`--${name}`);
  return i >= 0 && i + 1 < rest.length ? rest[i + 1] : dflt;
}

function requireToken() {
  const t = process.env.OPENCLAW_GATEWAY_TOKEN;
  if (!t) throw new Error('OPENCLAW_GATEWAY_TOKEN is required (injected inside the openclaw container).');
  return t;
}

function loadState() {
  const p = safeUserPath(userId);
  if (!fs.existsSync(p)) return { userId };
  try {
    return readJson(p);
  } catch (e) {
    // A truncated/corrupt state file (e.g. a kill mid-write before the atomic
    // rename landed, on an older volume) must not brick every future run.
    // `seen`/`extractedUnits` are best-effort dedup state, so start fresh.
    console.error(`⚠️ state file unreadable, starting fresh: ${e.message}`);
    return { userId };
  }
}
function saveState(state) {
  writeJson(safeUserPath(userId), state);
}

function getTz() {
  try {
    const p = safeUserPath(userId).replace(/\.json$/, '.prefs.json');
    if (fs.existsSync(p)) {
      const prefs = readJson(p);
      if (prefs && prefs.tz) return prefs.tz;
    }
  } catch (_) { /* fall through */ }
  return 'America/Los_Angeles';
}

// ---- fetch ---------------------------------------------------------------
// Pull the source field off a session payload, normalizing the two server
// shapes (`source` is the documented field; `source_kind` is tolerated).
function sessionSource(s) {
  return (s && (s.source || s.source_kind) || '').toString().trim().toLowerCase();
}
function sessionId(s) {
  return (s && (s.session_id || s.id) || '').toString().trim();
}

// Apply the single-unit filter shared by the CLI and tests. `--session` (audio)
// keeps the one non-keyboard session whose session_id matches; `--kbd-input`
// (keyboard) keeps the one keyboard entry whose session_id matches the
// keyboard_input.id the webhook fired for.
//
// Unit identity (locked by the spec): a keyboard unit is `kbd:<keyboard_input.id>`
// — the same id the webhook sends, the id `--kbd-input` filters on, and the id
// `unitKeyFor` derives from each event's source_ref. All three agree, so a unit
// the auto path flags is recognized by the manual path (cross-path idempotency).
//
// NOTE: for `--kbd-input` to actually resolve a row, /api/transcripts/recent must
// surface keyboard entries keyed by keyboard_input.id (source="keyboard",
// session_id=str(input id)). That server-side per-input emission is the one
// remaining dependency; until it lands the keyboard auto path fetches nothing and
// the unit stays unflagged for the manual gap-fill path to back-fill.
//
// Returns the filtered sessions array; with no filter the input is unchanged.
function filterToUnit(sessions, { sessionFilter, kbdFilter }) {
  if (sessionFilter) {
    return sessions.filter((s) => sessionSource(s) !== 'keyboard' && sessionId(s) === sessionFilter);
  }
  if (kbdFilter) {
    return sessions.filter((s) => sessionSource(s) === 'keyboard' && sessionId(s) === kbdFilter);
  }
  return sessions;
}

// IO-injectable core so doFetch is unit-testable. `deps.httpGet(url, token)`
// returns the parsed JSON body (the default hits javis-server via fetch).
async function doFetch(opts = {}, deps = {}) {
  const token = opts.token || requireToken();
  const httpGet = deps.httpGet || defaultHttpGet;
  const tz = deps.tz || getTz();
  const nowIso = deps.now ? deps.now() : new Date().toISOString();

  // --session (audio) / --kbd-input (keyboard) target one unit for the webhook
  // auto path; a unit outside the default window widens --hours as needed.
  // Tests inject opts.* directly; the CLI leaves them undefined and we read argv.
  const sessionFilter = 'sessionFilter' in opts ? opts.sessionFilter : getFlag('session', null);
  const kbdFilter = 'kbdFilter' in opts ? opts.kbdFilter : getFlag('kbd-input', null);
  const hours = 'hours' in opts ? opts.hours : (parseInt(getFlag('hours', '24'), 10) || 24);
  const limit = 'limit' in opts ? opts.limit : (parseInt(getFlag('limit', '50'), 10) || 50);
  const since = new Date(Date.now() - hours * 3600 * 1000).toISOString();
  const url = `${SERVER}/api/transcripts/recent?since=${encodeURIComponent(since)}&limit=${limit}`;
  const data = await httpGet(url, token);

  // Normalize to a sessions array regardless of the server envelope shape.
  const isEnvelope = data && typeof data === 'object' && !Array.isArray(data);
  let sessions = isEnvelope
    ? (Array.isArray(data.sessions) ? data.sessions : [])
    : (Array.isArray(data) ? data : []);

  sessions = filterToUnit(sessions, { sessionFilter, kbdFilter });

  // Anchor for relative-date resolution: the agent MUST resolve "tomorrow/Saturday/
  // next Thursday/around 6,7,8" against reference_time (real now) in tz — never its own
  // notion of "today". Preserve the server payload (sessions[]) alongside the anchor.
  const base = isEnvelope ? data : {};
  const out = { reference_time: nowIso, tz, ...base, sessions };
  if (deps.emit) deps.emit(out);
  else console.log(JSON.stringify(out, null, 2));
  return out;
}

async function defaultHttpGet(url, token) {
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error(`GET /api/transcripts/recent -> HTTP ${res.status}`);
  return res.json();
}

// ---- push helpers --------------------------------------------------------
function formatDigest(events, tz) {
  const lines = ['## 📅 Calendar — new meetings / 新会议', ''];
  for (const ev of events) {
    let when = ev.startAt
      ? new Date(ev.startAt).toLocaleString('en-US', { timeZone: tz })
      : 'time TBD';
    if (ev.startAt && ev.endAt) {
      when += ` – ${new Date(ev.endAt).toLocaleTimeString('en-US', { timeZone: tz })}`;
    }
    lines.push(`- **${ev.title}**`);
    lines.push(`  - 🕘 ${when}`);
    if (ev.location) lines.push(`  - 📍 ${ev.location}`);
    if (ev.attendees.length) lines.push(`  - 👥 ${ev.attendees.join(', ')}`);
    if (ev.notes) lines.push(`  - 📝 ${ev.notes}`);
  }
  return lines.join('\n');
}

async function pushToiOS(token, content) {
  const res = await fetch(`${SERVER}/api/agent/push`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ skill: SLUG, content }),
  });
  if (!res.ok) throw new Error(`POST /api/agent/push -> HTTP ${res.status}`);
}

async function mirrorToSkillData(token, events) {
  // Best-effort server-side mirror so the iOS app can read events via Clerk auth.
  // The container's gateway token can WRITE here, but cannot read back
  // (GET /api/skill/data requires a Clerk JWT) — so local state is the dedup
  // source of truth and this mirror is non-fatal.
  const items = events.slice(0, 500).map((ev) => ({
    dedup_key: dedupKey(ev),
    payload: { title: ev.title, location: ev.location, attendees: ev.attendees, notes: ev.notes },
    start_at: ev.startAt,
    end_at: ev.endAt,
    source_ref: ev.sourceRef,
  }));
  const res = await fetch(`${SERVER}/api/skill/data`, {
    method: 'POST',
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ skill: SLUG, type: 'event', merge: 'upsert', items }),
  });
  if (!res.ok) throw new Error(`POST /api/skill/data -> HTTP ${res.status}`);
}

// The two server writes the push paths perform, wrapped so tests can inject a
// recording mock instead of the real javis-server client. Each method takes the
// normalized events so a test can assert exactly which events hit the table.
const defaultPushClient = {
  mirror: (token, events) => mirrorToSkillData(token, events),
  push: (token, content) => pushToiOS(token, content),
};

// Read + parse + normalize the stdin events array, shared by both push paths.
async function readStdinEvents() {
  let input = '';
  for await (const chunk of process.stdin) input += chunk;
  input = input.trim();
  if (!input) throw new Error("push expects a JSON array of events on stdin (got empty input).");

  let parsed;
  try { parsed = JSON.parse(input); }
  catch (e) { throw new Error(`stdin is not valid JSON: ${e.message}`); }

  const rawEvents = Array.isArray(parsed)
    ? parsed
    : (Array.isArray(parsed.events) ? parsed.events : []);
  return rawEvents.map(normalizeEvent).filter(Boolean);
}

// ---- push: AUTO path (one unit, idempotent) ------------------------------
// Webhook-triggered: extract a single completed unit at most once. If the unit
// is already flagged in extractedUnits, no-op. Otherwise mirror -> push -> flag
// + cache. The event-level `seen` map is kept as a duplicate-event backstop.
async function doPushAuto(token, unitKey, deps = {}) {
  const client = deps.client || defaultPushClient;
  const load = deps.load || loadState;
  const save = deps.save || saveState;
  const tz = deps.tz || getTz();
  const events = deps.events || await readStdinEvents();

  const state = load();
  const extractedUnits = pruneExtractedUnits(state.extractedUnits || {});
  const seen = pruneSeen(state.seen || {});
  const nowIso = deps.now ? deps.now() : new Date().toISOString();

  if (extractedUnits[unitKey]) {
    // Idempotent: a duplicate/retried webhook (or a re-run) is a no-op.
    state.extractedUnits = extractedUnits;
    state.seen = seen;
    state.lastRunAt = nowIso;
    save(state);
    console.log(`already extracted: ${unitKey}`);
    return;
  }

  if (!events.length) {
    // Zero extracted events means we have nothing to write — and the fetch may
    // simply have raced the DB (the webhook beating the commit's visibility, or
    // replica lag). Do NOT flag the unit: leaving it unflagged lets a later
    // manual ask back-fill it (the spec's "manual fills gaps" safety net).
    // Flagging here would turn a transient miss into permanent unit loss.
    state.extractedUnits = extractedUnits;
    state.seen = seen;
    state.lastRunAt = nowIso;
    save(state);
    console.log(`No events extracted for ${unitKey}; left unflagged for manual gap-fill.`);
    return;
  }

  try { await client.mirror(token, events); }
  catch (e) { console.error('⚠️ skill_data mirror failed (non-fatal):', e.message); }

  const content = formatDigest(events, tz);
  await client.push(token, content);

  // Flag + cache the unit so we never re-extract it.
  extractedUnits[unitKey] = { ts: nowIso, events };
  for (const ev of events) seen[dedupKey(ev)] = nowIso;
  state.extractedUnits = extractedUnits;
  state.seen = seen;
  state.lastRunAt = nowIso;
  save(state);
  console.log(`Extracted ${events.length} event(s) for ${unitKey}, pushed to iOS.`);
}

// ---- push: MANUAL path (gap-fill) ----------------------------------------
// User-asked re-display. Already-flagged units are shown from cache only (no
// table write); not-yet-flagged units are extracted -> written -> pushed ->
// flagged + cached. One combined digest; only fresh units touch the table.
async function doPushManual(token, deps = {}) {
  const client = deps.client || defaultPushClient;
  const load = deps.load || loadState;
  const save = deps.save || saveState;
  const tz = deps.tz || getTz();
  const events = deps.events || await readStdinEvents();

  const state = load();
  const extractedUnits = pruneExtractedUnits(state.extractedUnits || {});
  const seen = pruneSeen(state.seen || {});
  const nowIso = deps.now ? deps.now() : new Date().toISOString();

  const { flaggedUnits, freshEvents } = partitionForManual(events, extractedUnits);

  // Fresh events are still passed through the event-level `seen` backstop so a
  // duplicate event (e.g. local volume wiped, unit flag lost) is not re-pushed.
  const freshNew = [];
  for (const ev of freshEvents) {
    const key = dedupKey(ev);
    if (!seen[key]) freshNew.push({ ev, key });
  }

  // Only fresh units touch the calendar table.
  if (freshNew.length) {
    try { await client.mirror(token, freshNew.map((f) => f.ev)); }
    catch (e) { console.error('⚠️ skill_data mirror failed (non-fatal):', e.message); }
  }

  // Build ONE combined digest: cached events from flagged units (display only)
  // + the freshly-extracted events.
  const cached = [];
  for (const u of flaggedUnits) cached.push(...u.events);
  const digestEvents = cached.concat(freshNew.map((f) => f.ev));

  if (!digestEvents.length) {
    state.extractedUnits = extractedUnits;
    state.seen = seen;
    state.lastRunAt = nowIso;
    save(state);
    console.log('No events to display.');
    return;
  }

  const content = formatDigest(digestEvents, tz);
  await client.push(token, content);

  // Flag + cache each fresh unit; record event-level dedup for fresh events.
  const byUnit = {};
  for (const f of freshNew) {
    seen[f.key] = nowIso;
    const uk = unitKeyFor(f.ev);
    if (uk) {
      if (!byUnit[uk]) byUnit[uk] = [];
      byUnit[uk].push(f.ev);
    }
  }
  for (const [uk, evs] of Object.entries(byUnit)) {
    extractedUnits[uk] = { ts: nowIso, events: evs };
  }

  state.extractedUnits = extractedUnits;
  state.seen = seen;
  state.lastRunAt = nowIso;
  save(state);
  console.log(
    `Displayed ${digestEvents.length} event(s) ` +
    `(${cached.length} cached + ${freshNew.length} freshly extracted).`
  );
}

// ---- push ----------------------------------------------------------------
async function doPush() {
  const token = requireToken();
  const unitKey = getFlag('unit', null);
  if (unitKey) return doPushAuto(token, unitKey);
  return doPushManual(token);
}

async function main() {
  parseArgv();
  if (subcommand === 'fetch') return doFetch();
  if (subcommand === 'push') return doPush();
  throw new Error(`Unknown subcommand '${subcommand}'. Use 'fetch' or 'push' (see --help).`);
}

// Export the load-bearing functions for unit tests (with injected IO). When run
// as a CLI (`node calendar-extractor.js …`) require.main is this module, so the
// entry point fires; under `require()` from a test it stays dormant.
module.exports = {
  doFetch,
  doPushAuto,
  doPushManual,
  filterToUnit,
  sessionSource,
  sessionId,
  formatDigest,
};

if (require.main === module) {
  main().catch((err) => {
    console.error('❌', err.message);
    process.exit(1);
  });
}
